package frc.robot;

import edu.wpi.first.wpilibj2.command.button.CommandXboxController;
import frc.robot.subsystems.Kicker.KickerConstants;

/**
 * Controller buttons that set subsystem states.
 *
 * GENERATED by 3161 Robot Setup from .robot-setup/bindings.json -- change
 * these in the app; edits to this file are overwritten. Hand-written
 * bindings belong in RobotContainer.configureBindings().
 */
final class ControllerBindings {
    private ControllerBindings() {
    }

    static void configure(CommandXboxController driver, CommandXboxController operator, RobotContainer robot) {
        // Operator back: Kicker -- hold for DEPLOY, release for STOW
        operator.back()
                .onTrue(robot.kicker.setWantedStateCommand(KickerConstants.WantedState.DEPLOY))
                .onFalse(robot.kicker.setWantedStateCommand(KickerConstants.WantedState.STOW));
    }
}
